import{_ as s,o as a,c as i,a3 as t}from"./chunks/framework.DH50UWNB.js";const k=JSON.parse(`{"title":"Install the CLI and sign in","description":"Install the wake CLI your agents' hooks run, put it on your PATH, sign in in the browser, with a token or in CI, and keep it updated.","frontmatter":{"description":"Install the wake CLI your agents' hooks run, put it on your PATH, sign in in the browser, with a token or in CI, and keep it updated."},"headers":[],"relativePath":"start/cli.md","filePath":"start/cli.md","lastUpdated":1794486787000}`),n={name:"start/cli.md"};function o(h,e,r,l,d,p){return a(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="install-the-cli-and-sign-in" tabindex="-1">Install the CLI and sign in <a class="header-anchor" href="#install-the-cli-and-sign-in" aria-label="Permalink to &quot;Install the CLI and sign in&quot;">​</a></h1><p><code>wake</code> is the command-line program that connects a repository to Wake and that your agent&#39;s hooks run. The hooks call it by name, so it must be on your <code>PATH</code>: an alias is not enough.</p><h2 id="install-the-cli" tabindex="-1">Install the CLI <a class="header-anchor" href="#install-the-cli" aria-label="Permalink to &quot;Install the CLI&quot;">​</a></h2><p>On the machine where you installed Wake, the installer already installed the CLI if Node.js 24 or newer and npm were present. Check:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line prompt"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><p>If it is missing there, <code>wake-server install-cli</code> installs it. On any other machine, such as a teammate&#39;s laptop, the same installer installs only the CLI:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line prompt"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/dalodev/wake-dist/releases/latest/download/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --cli-only</span></span></code></pre></div><p>It runs on Linux, macOS, and Windows inside WSL 2 (<a href="/wake-dist/docs/start/install#windows-with-wsl-2">Windows with WSL 2</a>), and needs:</p><ul><li>Node.js 24 or newer with npm;</li><li><code>curl</code>;</li><li>the tools that check the download&#39;s signature and checksums, as for the server: see <a href="/wake-dist/docs/start/install#what-you-need">What you need</a>.</li></ul><p>Before installing, it checks the download against the Wake release key, so a changed file installs nothing. It needs no Docker. It ends with <code>Next: wake login --server &lt;your Wake URL&gt;</code>. To check a download yourself, see <a href="/wake-dist/docs/reference/verify-installer">Verify a download</a>.</p><div class="info custom-block"><p class="custom-block-title">A teammate needs a shared Wake</p><p>A CLI on another machine signs in to a Wake it can reach over HTTPS: an installation made with <code>--domain</code>. A local installation answers only on its own machine (see <a href="/wake-dist/docs/start/install#who-can-reach-it">Who can reach it</a>).</p></div><h2 id="sign-in" tabindex="-1">Sign in <a class="header-anchor" href="#sign-in" aria-label="Permalink to &quot;Sign in&quot;">​</a></h2><p>You usually do not need to: <code>wake setup</code>, in <a href="/wake-dist/docs/start/first-project">Your first project</a>, signs the CLI in for you. Sign in yourself to use the CLI without <code>wake setup</code>, or when Wake asks you to.</p><h3 id="in-the-browser" tabindex="-1">In the browser <a class="header-anchor" href="#in-the-browser" aria-label="Permalink to &quot;In the browser&quot;">​</a></h3><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line prompt"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wake</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span></span></code></pre></div><p>On the machine where you installed Wake, <code>wake login</code> finds your Wake by itself. On any other machine, name it: <code>wake login --server &lt;your Wake URL&gt;</code>.</p><ol><li>It prints a code such as <code>BCDF-GHJK</code> and opens a page of your Wake in the browser.</li><li>Sign in to the web app if it asks, check that the code and the machine&#39;s name match, and choose the workspace (your personal one unless you pick another).</li><li>Choose <strong>Approve</strong>. The terminal prints <code>Logged in to ...</code> with your email, the workspace&#39;s name and its id in parentheses.</li></ol><p>Approve only a login you started yourself. The code expires after 10 minutes; run <code>wake login</code> again for a new one. Ctrl-C stops waiting.</p><ul><li><code>--no-browser</code> prints the code and the page&#39;s address without opening anything, so you can approve it on another device, such as your phone when you are connected over SSH.</li><li><code>--workspace &lt;id&gt;</code> signs in to that workspace; the browser offers only it.</li></ul><p>A connected repository names its workspace as <code>workspaceId</code> in <code>.wake/config.json</code>. To work in it, sign in to that workspace:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line prompt"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wake</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --server</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">your</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Wake</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> UR</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">L</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --workspace</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>When this machine has no login for it, your agent&#39;s session start names this command with the repository&#39;s values.</p><p>The CLI stays signed in for 90 days. Approving creates a personal access token named <code>wake CLI on &lt;machine&gt;</code>, which expires after 90 days and is kept in your system&#39;s keychain (or, without one, in a file only you can read). When it expires, your agent&#39;s session start says so and names the <code>wake login</code> command to run again. The token appears on the <strong>Tokens</strong> screen, linked in the web app&#39;s header at the top right; to sign that machine out, choose <strong>Revoke</strong> on its row and confirm.</p><h3 id="sign-in-with-a-token" tabindex="-1">Sign in with a token <a class="header-anchor" href="#sign-in-with-a-token" aria-label="Permalink to &quot;Sign in with a token&quot;">​</a></h3><p>Where no browser can approve a login, such as a script, create a token in the web app: open <strong>Tokens</strong>, enter a name such as your machine&#39;s, choose <strong>Create token</strong> and copy the secret (Wake shows it only once). Then run <code>wake login --with-token</code> and paste it when asked; it is not echoed. A token piped on standard input works the same way, for example from your password manager&#39;s command line, so it never sits in a file or your shell history.</p><h3 id="in-ci" tabindex="-1">In CI <a class="header-anchor" href="#in-ci" aria-label="Permalink to &quot;In CI&quot;">​</a></h3><p>Skip <code>wake login</code>: give the token as <code>WAKE_TOKEN</code> and your Wake URL as <code>WAKE_SERVER</code>, both from the pipeline&#39;s secrets:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line prompt"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">WAKE_SERVER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://wake.example.com</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> WAKE_TOKEN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$WAKE_CI_TOKEN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> wake</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sync</span></span></code></pre></div><p>The CLI sends <code>WAKE_TOKEN</code> only to the server <code>WAKE_SERVER</code> names. With <code>WAKE_TOKEN</code> set and no <code>WAKE_SERVER</code>, it stops with <code>WAKE_TOKEN is set without WAKE_SERVER; set WAKE_SERVER to the server the token belongs to</code>. When a command would call another server, for example one a pull request wrote into the repository&#39;s <code>.wake/config.json</code>, it stops with a line naming both servers and sends nothing.</p><h2 id="update-the-cli" tabindex="-1">Update the CLI <a class="header-anchor" href="#update-the-cli" aria-label="Permalink to &quot;Update the CLI&quot;">​</a></h2><p>The server and the CLI update separately. Your server upgrades itself daily, or when you run <code>wake-server upgrade</code>. Each CLI updates itself at the next agent session once its server recommends a newer one, for a CLI installed globally as the installer does, and never in CI. <code>wake upgrade</code> updates it now; on the machine where you installed Wake it upgrades the server first. Set <code>WAKE_AUTO_UPGRADE=off</code> to turn the automatic update off. See <a href="/wake-dist/docs/run/upgrade">Upgrade</a>.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><p><a href="/wake-dist/docs/start/first-project">Your first project</a>.</p>',33)])])}const g=s(n,[["render",o]]);export{k as __pageData,g as default};
